@import url('./assets/fonts/local-fonts.css');
:root{--ink:#d4d0c3;--dim:#77796f;--faint:#41443c;--red:#c04836;--red-glow:#a32920;--gold:#d0ad73;--panel:rgba(7,10,9,.78);--mono:'Share Tech Mono',monospace;--cond:'Barlow Condensed',sans-serif;--serif:'Cinzel',serif}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050707;color:var(--ink);font-family:var(--cond);user-select:none}body{letter-spacing:.045em}button,input{font:inherit;color:inherit}button{cursor:pointer}#game{position:fixed;inset:0;width:100%;height:100%;display:block;z-index:0}.film-grain{position:fixed;inset:-50%;z-index:4;pointer-events:none;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.94' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");animation:grain .22s steps(2) infinite}.vignette{position:fixed;inset:0;z-index:3;pointer-events:none;background:radial-gradient(ellipse at 49% 49%,transparent 23%,rgba(0,0,0,.24) 64%,rgba(0,0,0,.88) 120%);transition:opacity 1s}.flash{position:fixed;inset:0;background:#d8cbb1;opacity:0;z-index:12;pointer-events:none}.flash.burst{animation:flash .4s ease-out}@keyframes flash{0%{opacity:.7}100%{opacity:0}}@keyframes grain{0%{transform:translate(1%,1%)}50%{transform:translate(-1%,-1%)}100%{transform:translate(1%,-1%)}}
#topline{position:fixed;z-index:7;top:25px;left:40px;right:42px;display:flex;align-items:center;gap:14px;color:#a6a89b;font:11px var(--mono);letter-spacing:.2em;transition:opacity .5s}.brand-mark{font:24px var(--serif);color:#dad7cd}.brand-mark span{color:var(--red)}#top-caption{opacity:.66}.icon-btn{margin-left:auto;background:none;border:0;color:#a5a399;font-size:19px;opacity:.75}.screen{position:fixed;inset:0;z-index:5;display:none}.screen.visible{display:flex}.screen#main-menu{align-items:center}.menu-content{position:relative;margin-left:12.2vw;margin-top:3vh;width:min(470px,43vw);z-index:2;animation:arrive 1.2s cubic-bezier(.16,.76,.25,1) both}@keyframes arrive{from{opacity:0;transform:translateY(17px)}to{opacity:1;transform:none}}.eyebrow{font:10px var(--mono);letter-spacing:.22em;color:#9b9b8e}.menu-content .eyebrow{display:flex;align-items:center;gap:12px}.menu-content .eyebrow i{width:24px;height:1px;background:var(--red);display:inline-block}.title{font:500 clamp(43px,5.25vw,78px)/.98 var(--serif);letter-spacing:.025em;margin:28px 0 9px;color:#e2ded1;text-shadow:0 2px 20px #000}.title-null{display:block;color:#9c978a;font-weight:500;letter-spacing:.12em;font-size:.57em;margin:10px 0 0 5px}.creator{font:300 17px var(--cond);color:#c6b790;letter-spacing:.19em;text-shadow:0 0 12px rgba(205,176,112,.25);margin:18px 0 22px 4px}.rule{height:1px;width:100%;background:linear-gradient(90deg,#6e6350,rgba(180,164,132,.12) 76%,transparent)}.rule span{position:absolute;width:37px;height:1px;background:var(--red);box-shadow:0 0 9px var(--red);left:0}.tagline{font:500 14px var(--mono);letter-spacing:.25em;color:#c5c2b5;margin:28px 0 24px}.menu-buttons{display:flex;flex-direction:column;gap:3px}.menu-btn{position:relative;width:100%;height:47px;border:1px solid transparent;text-align:left;background:rgba(18,21,19,.58);display:flex;align-items:center;padding:0 16px;gap:16px;font:500 15px var(--cond);letter-spacing:.18em;color:#aaa99e;transition:.25s;backdrop-filter:blur(4px)}.menu-btn:hover,.menu-btn:focus-visible{border-color:rgba(199,180,144,.36);background:rgba(38,39,34,.78);color:#eee9da;padding-left:21px}.menu-btn.primary{border-left:2px solid var(--red);background:linear-gradient(90deg,rgba(110,35,27,.34),rgba(17,19,17,.75) 62%);color:#e4ddcb}.menu-btn.primary:hover{border-color:rgba(208,173,115,.55);box-shadow:0 0 25px rgba(131,44,31,.18)}.menu-btn b{font:18px var(--cond);margin-left:auto;color:#777}.menu-btn.primary b{color:#d39c76}.btn-index{font:10px var(--mono);color:#8f8a7d}.menu-btn.quiet{margin-top:5px;background:transparent;color:#72736a}.menu-foot{display:flex;justify-content:space-between;margin-top:29px;font:9px var(--mono);letter-spacing:.13em;color:#77796e}.amber{color:#bd5e49}.menu-side-note{position:absolute;right:8vw;top:38%;height:188px;display:flex;flex-direction:column;justify-content:space-between;align-items:flex-end;color:rgba(185,183,165,.35);font:9px var(--mono);letter-spacing:.2em}.side-line{height:105px;width:1px;background:linear-gradient(transparent,#7f2520 45%,transparent)}.menu-bottom{position:absolute;bottom:25px;left:40px;right:42px;display:flex;justify-content:space-between;font:9px var(--mono);color:rgba(183,182,168,.38);letter-spacing:.14em}.panel-screen{align-items:center;justify-content:center;backdrop-filter:blur(4px);background:radial-gradient(ellipse at 55% 52%,rgba(14,17,15,.72),rgba(3,5,5,.9))}.panel-card{position:relative;width:min(620px,90vw);padding:52px 60px 42px;border:1px solid rgba(156,146,119,.24);background:linear-gradient(140deg,rgba(21,24,21,.94),rgba(7,9,8,.95));box-shadow:0 30px 120px #000;animation:arrive .4s ease-out}.panel-card:before{content:'';position:absolute;top:-1px;left:34px;width:68px;height:1px;background:var(--red);box-shadow:0 0 9px var(--red)}.panel-card h2{font:500 34px var(--serif);letter-spacing:.09em;margin:13px 0 31px;color:#e4dfd1}.close-btn{position:absolute;right:22px;top:17px;border:0;background:none;color:#85877d;font:13px var(--mono);letter-spacing:.1em}.close-btn:hover{color:#eee}.setting-row{display:flex;align-items:center;justify-content:space-between;padding:18px 0;border-top:1px solid rgba(170,165,144,.12)}.setting-row label{display:block;font:500 15px var(--cond);letter-spacing:.14em;color:#d1cec0}.setting-row small{display:block;margin-top:5px;color:#77796e;font:9px var(--mono);letter-spacing:.09em}.segmented{border:1px solid #44463f;display:flex}.segmented button{width:43px;height:31px;border:0;background:transparent;color:#77786e;font:11px var(--mono)}.segmented button.selected{background:#604136;color:#f0d7b3;box-shadow:inset 0 -1px var(--gold)}input[type=range]{width:132px;accent-color:#ad6148}.toggle{border:1px solid #656555;background:#3c4738;color:#c4d2b5;padding:7px 17px;font:10px var(--mono);letter-spacing:.1em}.toggle.off{background:#3a312e;color:#b07a70}.setting-value{font:10px var(--mono);color:#ba9971;letter-spacing:.12em}.panel-note{margin-top:24px;padding-top:14px;border-top:1px solid rgba(170,165,144,.12);font:9px/1.7 var(--mono);letter-spacing:.08em;color:#77796f}.panel-intro{font:12px var(--mono);letter-spacing:.1em;color:#aaa99e;margin:-18px 0 22px}.lobby-card{width:min(720px,94vw);padding:47px 52px 32px}.lobby-card h2{margin-bottom:13px}.lobby-options{display:flex;flex-direction:column;gap:6px}.lobby-option{position:relative;display:flex;align-items:center;width:100%;min-height:67px;padding:10px 15px;background:rgba(38,40,34,.42);border:1px solid rgba(149,143,124,.12);text-align:left;gap:16px;transition:.2s}.lobby-option:hover{background:rgba(66,52,40,.48);border-color:rgba(208,173,115,.36)}.lobby-icon{font:24px var(--serif);color:#b48d62;width:29px;text-align:center}.lobby-option b{display:block;font:500 15px var(--cond);letter-spacing:.13em;color:#d5d1c5}.lobby-option small{display:block;font:9px var(--mono);letter-spacing:.08em;color:#77796d;margin-top:4px}.lobby-option em{font:10px var(--mono);font-style:normal;color:#77796d;margin-left:auto}.join-option input{width:76px;margin-left:auto;background:#0b0e0d;border:1px solid #42433b;padding:8px;color:#e3c28e;text-align:center;letter-spacing:.2em;text-transform:uppercase;font:14px var(--mono)}.mini-button{background:rgba(155,102,69,.17);border:1px solid rgba(208,173,115,.28);color:#d4b68a;padding:8px 11px;font:10px var(--mono);letter-spacing:.1em;transition:.2s}.mini-button:hover{background:rgba(155,102,69,.36)}.lobby-status{text-align:center;margin:15px 0 0;font:10px var(--mono);letter-spacing:.1em;color:#77796e}.room-card{width:min(570px,90vw);text-align:center}.room-card h2{margin-bottom:15px}.room-code-label{font:10px var(--mono);letter-spacing:.26em;color:#88897d}.room-code{font:500 48px var(--mono);letter-spacing:.3em;color:#e1c28d;text-shadow:0 0 25px rgba(192,139,83,.28);margin:9px 0}.squad-list{margin:27px 0 17px;text-align:left;border-top:1px solid #33352f}.squad-member{height:49px;display:flex;align-items:center;gap:13px;border-bottom:1px solid #292c27;font:11px var(--mono);color:#c7c3b4}.squad-member small{margin-left:auto;color:#7a7b71;font:9px var(--mono)}.squad-member.waiting{color:#77796f}.online-dot{width:6px;height:6px;border-radius:50%;background:#75a177;box-shadow:0 0 8px #60935f}.bot-dot{background:#be8d5b;box-shadow:0 0 8px #9f7045}.room-actions{display:flex;align-items:center;gap:14px}.room-actions .menu-btn{flex:1}.room-card .panel-note{text-align:left}
