function beginIntro(){game.mode='intro';setScreen('intro-screen');$('#intro-title').innerHTML='SOMEWHERE BELOW YOU,<br>IT IS ALREADY AWAKE.';$('#intro-text').innerHTML='The recorder clicks. A voice—hoarse, terrified—fills the dark.<br>“If the lights are dead, don\'t make a sound. It follows the noise.”';$('#intro-subtitle').textContent='';$('#intro-screen').querySelector('.intro-progress span').style.width='0';let progress=0;clearInterval(beginIntro.timer);beginIntro.timer=setInterval(()=>{progress+=2.5;$('#intro-screen').querySelector('.intro-progress span').style.width=Math.min(100,progress)+'%';if(progress>=100){clearInterval(beginIntro.timer);beginGame();}},240);}

function nearInteraction(){let best=null,bestD=Infinity;for(const it of interactables){if(it.used)continue;const d=player.pos.distanceTo(it.pos);if(d<it.r&&d<bestD){best=it;bestD=d;}}return best;}
function toggleFlashlight(){if(!game.hasFlashlight||game.battery<=0){showToast(tr('Taschenlampe ohne Ladung.','Flashlight battery depleted.'));return;}flashOn=!flashOn;flashlight.intensity=flashOn?3.1:0;flashlight.userData.fill.intensity=flashOn?.32:0;$('#equipment').innerHTML=tr(`${flashOn?'▰':'▱'} Taschenlampe <span>◉ Walkie-talkie</span>`,`${flashOn?'▰':'▱'} Flashlight <span>◉ Walkie-talkie</span>`);playTone(flashOn?420:190,.06,'square',.025);}
function moveAxis(axis,amount){if(!amount)return;const next=player.pos.clone();next[axis]+=amount;const radius=.32;for(const c of colliders){if(c.disabled)continue;const hx=c.w/2+radius,hz=c.d/2+radius;if(Math.abs(next.x-c.x)<hx&&Math.abs(next.z-c.z)<hz&&player.pos.y<c.h+.25){return;}}player.pos[axis]=next[axis];}
function damage(amount){if(game.damageCooldown>0||game.playerDown||game.mode!=='playing')return;game.health=Math.max(0,game.health-amount);game.damageCooldown=1.15;$('#damage-vignette').style.opacity='.78';setTimeout(()=>$('#damage-vignette').style.opacity='0',240);playTone(58,.22,'sawtooth',.1);if(game.health<=0){game.playerDown=true;$('#down-overlay').classList.add('show');game.revive=0;}}
function setPaused(value){if(game.mode!=='playing')return;game.paused=value;$('#pause-screen').classList.toggle('show',value);if(value)document.exitPointerLock?.();else renderer.domElement.requestPointerLock?.();}
function updateMonster(dt){if(!monster?.userData.active)return;monster.visible=true;const to=player.pos.clone().sub(monster.position);to.y=0;const dist=to.length();game.enemyDist=dist;game.enemyAlert=Math.max(game.enemyAlert,clamp(1-dist/22,0,1));const dir=to.normalize();const speed=game.called?1.48+Math.max(0,1-game.hold/60)*.28:1.05;monster.position.addScaledVector(dir,speed*dt);monster.rotation.y=Math.atan2(dir.x,dir.z);monster.position.y=.025+Math.sin(game.elapsed*5)*.035;if(dist<1.38)damage(game.called?22:14);monsterLight.intensity=1.1+Math.sin(game.elapsed*9)*.35;}
function updateBots(dt){for(let i=0;i<bots.length;i++){const bot=bots[i],off=bot.userData.offset;const target=new THREE.Vector3(player.pos.x+off.x,0,player.pos.z+off.z);const delta=target.sub(bot.position);delta.y=0;const d=delta.length();if(d>1.3){delta.normalize();bot.position.addScaledVector(delta,Math.min(d-1.1,2.25*dt));bot.rotation.y=Math.atan2(delta.x,delta.z);}}}
function updateHud(dt){const battery=$('#battery-meter');if(battery){battery.querySelector('b').textContent=`${Math.ceil(game.battery)}%`;battery.querySelector('i').style.width=`${game.battery}%`;battery.classList.toggle('low',game.battery<20);}$('#fear-vignette').style.opacity=String(clamp(game.fear/150,0,.72));if(game.called&&game.hold>0){$('#objective-text').textContent=`${objectives[game.lang][5]}  ·  ${Math.ceil(game.hold)}s`;}if(game.playerDown){game.revive+=dt*(bots.length?1/7:0);$('#down-overlay .revive-meter i').style.width=`${clamp(game.revive*100,0,100)}%`;if(game.revive>=1){game.playerDown=false;game.health=35;$('#down-overlay').classList.remove('show');showToast(tr('Dein Team hat dich stabilisiert.','Your team stabilized you.'));}}}
function update(dt){game.elapsed+=dt;game.damageCooldown=Math.max(0,game.damageCooldown-dt);if(game.called&&game.hold>0){game.hold=Math.max(0,game.hold-dt);if(game.hold===0){updateObjectives();showToast(tr('Aufzug bereit. Erreiche das Bedienfeld!','Elevator ready. Reach the control panel!'),3600);}}if(!game.paused&&!game.playerDown){const forward=(keysDown.has('KeyW')||keysDown.has('ArrowUp')?1:0)-(keysDown.has('KeyS')||keysDown.has('ArrowDown')?1:0);const side=(keysDown.has('KeyD')||keysDown.has('ArrowRight')?1:0)-(keysDown.has('KeyA')||keysDown.has('ArrowLeft')?1:0);const moving=forward!==0||side!==0;const sprint=moving&&(keysDown.has('ShiftLeft')||keysDown.has('ShiftRight'))&&game.stamina>2;const speed=sprint?5.15:3.05;if(sprint)game.stamina=Math.max(0,game.stamina-24*dt);else game.stamina=Math.min(100,game.stamina+15*dt);const f=new THREE.Vector3(Math.sin(player.yaw),0,-Math.cos(player.yaw)),r=new THREE.Vector3(Math.cos(player.yaw),0,Math.sin(player.yaw));const v=f.multiplyScalar(forward).add(r.multiplyScalar(side));if(v.lengthSq()>0)v.normalize().multiplyScalar(speed*dt);moveAxis('x',v.x);moveAxis('z',v.z);if(moving){bob+=dt*(sprint?11:7);footstep-=dt;if(footstep<=0){footstep=sprint?.28:.48;playTone(sprint?78:95,.035,'triangle',sprint?.045:.018);game.noise=sprint?1:.4;}}else game.noise=Math.max(0,game.noise-dt);camera.position.set(player.pos.x,1.66+Math.sin(bob)*.025,player.pos.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');if(flashOn&&game.battery>0){game.battery=Math.max(0,game.battery-(.22+(sprint?.28:0))*dt);if(game.battery===0){flashOn=false;flashlight.intensity=0;flashlight.userData.fill.intensity=0;showToast(tr('Die Taschenlampe ist erloschen.','The flashlight has gone dark.'));}}}updateMonster(dt);updateBots(dt);if(monster?.userData.active){const near=clamp(1-game.enemyDist/18,0,1);game.fear=clamp(game.fear+(near*9-(1-near)*2)*dt,0,100);}else game.fear=Math.max(0,game.fear-4*dt);const current=nearInteraction();$('#interaction').classList.toggle('show',!!current&&!game.paused&&!game.playerDown);if(current)$('#interaction-text').textContent=current.label;updateHud(dt);}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,Math.max(0,(now-lastTime)/1000||0));lastTime=now;for(const f of flickers){const wave=.88+.12*Math.sin(now*.0018+f.phase);f.light.intensity=f.base*wave*(Math.random()>.996?.12:1);}for(const p of particles){const a=p.points.geometry.attributes.position;for(let i=0;i<p.speeds.length;i++){a.array[i*3+1]+=(Math.sin(now*.0003+i)*.15)*dt;a.array[i*3+2]+=p.speeds[i]*dt;if(a.array[i*3+2]>18)a.array[i*3+2]=-82;}a.needsUpdate=true;}if(game.mode==='playing'&&!game.paused)update(dt);if(composer){composer.render();}else renderer.render(scene,camera);}

function handleAction(action){switch(action){case'intro':beginIntro();break;case'settings':setScreen('settings-screen');break;case'lobby':game.botCount=1;localize();setScreen('lobby-screen');break;case'back':setScreen(game.mode==='menu'?'main-menu':'lobby-screen');break;case'backLobby':setScreen('lobby-screen');break;case'host':case'quick':game.roomCode=Math.random().toString(36).slice(2,6).toUpperCase();$('#room-code').textContent=game.roomCode;$('#lobby-status').textContent=tr('LOKALER TESTRAUM · KEIN ONLINE-MATCHMAKING','LOCAL TEST LOBBY · NO ONLINE MATCHMAKING');setScreen('room-screen');break;case'offline':game.botCount=1;setupRoomBots();setScreen('room-screen');break;case'launch':beginGame();break;case'resume':setPaused(false);break;case'quit':case'menu':game.mode='menu';game.paused=false;game.ending=false;$('#game-ui').classList.remove('active');$('#ending-screen').classList.remove('show');$('#pause-screen').classList.remove('show');setScreen('main-menu');document.exitPointerLock?.();break;}}
function setupRoomBots(){game.roomCode=tr('OFFLINE · KI-TEAM','OFFLINE · BOT TEAM');$('#room-code').textContent=game.roomCode;$('#lobby-status').textContent=tr('OFFLINE-KI-TEAM · LOKALES SPIEL','OFFLINE BOT TEAM · LOCAL GAME');}
function wireUI(){document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action){handleAction(action);return;}const lang=e.target.closest('[data-lang]')?.dataset.lang;if(lang){game.lang=lang;$$('[data-lang]').forEach(b=>b.classList.toggle('selected',b.dataset.lang===lang));localize();updateObjectives();return;}});$('#skip-intro').addEventListener('click',()=>{clearInterval(beginIntro.timer);beginGame();});$('#subtitle-toggle').addEventListener('click',e=>{game.subtitleOn=!game.subtitleOn;e.currentTarget.classList.toggle('on',game.subtitleOn);e.currentTarget.textContent=game.subtitleOn?'ON':'OFF';});$('#copy-code').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(game.roomCode);showToast(tr('Raumcode kopiert.','Room code copied.'));}catch{showToast(game.roomCode);}});$('#fill-bots').addEventListener('click',()=>{game.botCount=3;$('#bot-row').style.display='flex';$('#lobby-status').textContent=tr('KI-TEAM EINSATZBEREIT · 3 OPERATIVE','BOT SQUAD READY · 3 OPERATIVES');});$('#join-button').addEventListener('click',()=>{const code=$('#join-code').value.trim().toUpperCase();$('#lobby-status').textContent=code?tr('CODE IST LOKAL · ONLINE-SERVER NICHT VERFÜGBAR','CODE IS LOCAL · NO ONLINE SERVER AVAILABLE'):tr('BITTE EINEN 4-STELLIGEN CODE EINGEBEN','ENTER A FOUR-CHARACTER CODE');});$('#sound-toggle').addEventListener('click',()=>{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();playTone(440,.1,'sine',.04);});$('#game').addEventListener('click',()=>{if(game.mode==='playing'&&!game.paused&&!pointer)renderer.domElement.requestPointerLock?.();});document.addEventListener('pointerlockchange',()=>{pointer=document.pointerLockElement===renderer.domElement;});document.addEventListener('mousemove',e=>{if(pointer&&game.mode==='playing'&&!game.paused){const sens=Number($('#sensitivity-slider').value)/80*.0022;player.yaw-=e.movementX*sens;player.pitch=clamp(player.pitch-e.movementY*sens,-1.45,1.45);}});document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keysDown.add(e.code);if(e.repeat)return;if(e.code==='Escape'&&game.mode==='playing'){setPaused(!game.paused);return;}if(game.mode!=='playing')return;if(e.code==='KeyE'&&!game.paused){if(game.playerDown){game.revive=Math.min(1,game.revive+.08);return;}const it=nearInteraction();if(it){it.fn();if(it.kind==='item')it.used=true;}return;}if(e.code==='KeyF'&&!game.paused)toggleFlashlight();if(e.code==='KeyJ'&&!game.paused)$('#objective-log').classList.toggle('open');if(e.code==='KeyQ'&&!game.paused&&game.hasRadio){playTone(620,.07,'square',.03);showToast(tr('FUNKRAUSCHEN · KEIN SIGNAL','RADIO STATIC · NO SIGNAL'),1200);}});document.addEventListener('keyup',e=>keysDown.delete(e.code));window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);if(composer)composer.setSize(innerWidth,innerHeight);});}

