import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();
const browser = await chromium.launch({...config.browser.launchOptions,args:[...config.browser.launchOptions.args,'--no-sandbox']});
const page = await browser.newPage({viewport:{width:1280,height:720}});
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
page.on('console', m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://127.0.0.1:8000/',{waitUntil:'networkidle'});
await page.locator('[data-action="intro"]').click();
console.log('INTRO',await page.locator('#intro-screen').getAttribute('class'));
await page.locator('#skip-intro').click();
await page.waitForTimeout(300);
const move=async(key,ms)=>{await page.keyboard.down(key);await page.waitForTimeout(ms);await page.keyboard.up(key);await page.waitForTimeout(180)};
const interact=async()=>{await page.keyboard.press('KeyE');await page.waitForTimeout(250)};
const state=async(label)=>console.log(label,{objective:(await page.locator('#objective-text').textContent()).trim(),interaction:(await page.locator('#interaction-text').textContent()).trim(),toast:(await page.locator('#toast').textContent()).trim()});
await state('START');
await move('KeyS',520);
await state('NEAR JOURNAL');
await interact();
await state('AFTER JOURNAL');
await move('KeyW',2500);
await move('KeyD',500);
await state('NEAR SECURITY PANEL');
await interact();
await state('AFTER SECURITY');
await move('KeyA',1650);
await move('KeyW',5000);
await state('NEAR MED CARD');
await interact();
await state('AFTER MED CARD');
console.log('ERRORS',errors);
await browser.close();

