import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();
const browser = await chromium.launch({...config.browser.launchOptions,args:[...config.browser.launchOptions.args,'--no-sandbox']});
const page = await browser.newPage({viewport:{width:1280,height:720}});
const errors=[];
page.on('pageerror', e=>errors.push('PAGE '+e.message));
page.on('response', r=>{if(r.status()>=400)errors.push('HTTP '+r.status()+' '+r.url())});
page.on('requestfailed', r=>errors.push('FAILED '+r.url()+' '+r.failure()?.errorText));
page.on('console', m=>{if(m.type()==='error')errors.push('CONSOLE '+m.text())});
await page.goto('http://127.0.0.1:8000/',{waitUntil:'commit',timeout:10000}); await page.waitForTimeout(2500);
await page.locator('[data-action="intro"]').evaluate(el=>el.click());
await page.locator('#skip-intro').click({force:true}); await page.waitForTimeout(300);
const move=async(key,ms)=>{await page.keyboard.down(key);await page.waitForTimeout(ms);await page.keyboard.up(key);await page.waitForTimeout(100)};
const interact=async()=>{await page.keyboard.press('e');await page.waitForTimeout(250)};
const state=async(label)=>console.log(label,{objective:(await page.locator('#objective-text').textContent()).trim(),interaction:(await page.locator('#interaction-text').textContent()).trim(),toast:(await page.locator('#toast').textContent()).trim()});
await move('s',520); await state('DESK'); await interact(); await state('RADIO PICKED'); await interact(); await state('JOURNAL READ');
await move('w',3100); await move('d',780); await state('SECURITY PANEL'); await interact(); await state('SECURITY UNLOCK');
await move('a',800); await move('w',300); await move('w',3900); await move('a',1300); await state('MED KEYCARD'); await interact(); await state('MED CARD COLLECTED');
console.log('ERRORS',errors);
await browser.close();

