import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, args: [...config.browser.launchOptions.args, '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push(`PAGE ${e.message}`));
page.on('response', r => { if (r.status() >= 400 && !r.url().endsWith('/favicon.ico')) errors.push(`HTTP ${r.status()} ${r.url()}`); });
page.on('requestfailed', r => errors.push(`FAILED ${r.url()} ${r.failure()?.errorText}`));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push(`CONSOLE ${m.text()}`); });
const wait = ms => page.waitForTimeout(ms);
const state = () => page.evaluate(() => window.__facilityDebug());
const move = async (key, ms) => { if (ms <= 0) return; await page.keyboard.down(key); await wait(ms); await page.keyboard.up(key); await wait(120); };
const travelTo = async (x, z) => {
  for (const [axis, goal, positive, negative] of [['z', z, 'KeyS', 'KeyW'], ['x', x, 'KeyD', 'KeyA']]) {
    for (let attempt = 0; attempt < 6; attempt++) {
      const p = (await state()).pos;
      const delta = goal - p[axis === 'x' ? 0 : 2];
      if (Math.abs(delta) < .32) break;
      const key = delta > 0 ? positive : negative;
      await move(key, Math.max(130, Math.abs(delta) / 2.8 * 1000));
    }
  }
  const p = (await state()).pos;
  assert.ok(Math.hypot(p[0] - x, p[2] - z) < 1.2, `Could not walk to ${x},${z}; actual ${p[0]},${p[2]}`);
};
const interact = async label => {
  await page.keyboard.press('KeyE'); await wait(180);
  const s = await state();
  console.log(label, { pos: s.pos, phase: s.phase, keycards: s.keycards, power: s.power, called: s.elevatorCalled, seconds: Math.ceil(s.survivalSeconds), storyRead: s.storyRead, nearest: s.nearestInteraction, toast: (await page.locator('#toast').textContent())?.trim() });
  return s;
};
try {
  await page.goto('http://127.0.0.1:8000/', { waitUntil: 'domcontentloaded', timeout: 90000 });
  await wait(1200);
  await page.locator('[data-action="intro"]').click();
  await page.locator('#skip-intro').click({ force: true });
  await wait(350);
  console.log('START', await state());
  await interact('journal');
  assert.equal((await state()).storyRead, true, 'Journal interaction did not advance story');
  await travelTo(2.4, -4.4);
  const security = await interact('security unlock');
  assert.ok(security.phase >= 1, 'Security door interaction did not advance phase');
  console.log('ERRORS', errors);
} finally { await browser.close(); }

