for (let attempt = 0; attempt < 6; attempt++) {
  const p = (await state()).pos;
  const delta = goal - p[axis === 'x' ? 0 : 2];
  if (Math.abs(delta) < .32) break;
  const key = delta > 0 ? positive : negative;
  await move(key, Math.max(130, Math.abs(delta) / 2.8 * 1000));
  const after = await state(); console.log('MOVE', axis, key, 'to', goal, 'now', after.pos);
}

