for (let attempt = 0; attempt < 24; attempt++) {
  const p = (await state()).pos;
  const delta = goal - p[axis === 'x' ? 0 : 2];
  if (Math.abs(delta) < .3) break;
  const key = delta > 0 ? positive : negative;
  await move(key, Math.min(650, Math.max(200, Math.abs(delta) / 2.8 * 1000)));
}

