import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, args: [...config.browser.launchOptions.args, '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push(`PAGE ${e.message}`));
page.on('response', r => { if (r.status() >= 400 && !r.url().endsWith('/favicon.ico')) errors.push(`HTTP ${r.status()} ${r.url()}`); });
page.on('requestfailed', r => errors.push(`FAILED ${r.url()} ${r.failure()?.errorText}`));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push(`CONSOLE ${m.text()}`); });
const wait = ms => page.waitForTimeout(ms);
const state = () => page.evaluate(() => window.__facilityDebug());
const move = async (key, ms) => { if (ms <= 0) return; await page.keyboard.down(key); await wait(ms); await page.keyboard.up(key); await wait(100); };
const dirKey = (dx,dz) => Math.abs(dx) > Math.abs(dz) ? (dx > 0 ? 'd':'a') : (dz > 0 ? 's':'w');
const walkTo = async (x,z) => {
  const step = .35;
  for (let outer=0;outer<10;outer++) {
    const s=await state(), [sx,,sz]=s.pos;
    if(Math.hypot(sx-x,sz-z)<.48) return;
    const cs=s.colliders.filter(c=>!c.disabled);
    const nx=Math.round(12/step), nz=Math.round(88/step), key=(ix,iz)=>`${ix},${iz}`;
    const toGrid=(x,z)=>[Math.round((x+6)/step),Math.round((z+86)/step)];
    const fromGrid=(ix,iz)=>[-6+ix*step,-86+iz*step];
    const [si,sj]=toGrid(sx,sz),[gi,gj]=toGrid(x,z);
    const blocked=(i,j)=>{if(i<1||i>nx-1||j<1||j>nz-1)return true;const [px,pz]=fromGrid(i,j);return cs.some(c=>Math.abs(px-c.x)<c.w/2+.39&&Math.abs(pz-c.z)<c.d/2+.39);};
    const q=[[si,sj]], prev=new Map([[key(si,sj),null]]);let found=false;
    for(let n=0;n<q.length;n++){const [i,j]=q[n];if(Math.hypot(i-gi,j-gj)<=1.4){found=true;break;}for(const [di,dj] of [[1,0],[-1,0],[0,1],[0,-1]]){const a=i+di,b=j+dj,k=key(a,b);if(!prev.has(k)&&!blocked(a,b)){prev.set(k,[i,j]);q.push([a,b]);}}}
    if(!found) throw new Error(`No path ${sx.toFixed(1)},${sz.toFixed(1)} -> ${x},${z}`);
    let end=q.find(([i,j])=>Math.hypot(i-gi,j-gj)<=1.4),path=[];while(end){path.push(end);end=prev.get(key(...end));}path.reverse();
    // Walk toward a far point on the grid route; recompute after each segment to account for collision edges.
    let wp=path[Math.min(path.length-1,5)];let [wx,wz]=fromGrid(...wp);const dx=wx-sx,dz=wz-sz;
    if(Math.abs(dx)+Math.abs(dz)<.12){wp=path[Math.min(path.length-1,9)];[wx,wz]=fromGrid(...wp);}
    const now=await state(),dX=wx-now.pos[0],dZ=wz-now.pos[2],axis=dirKey(dX,dZ),dist=Math.abs(axis==='d'||axis==='a'?dX:dZ);
    await move(axis,Math.max(80,dist/3.05*1000));
  }
  const p=(await state()).pos;assert.ok(Math.hypot(p[0]-x,p[2]-z)<1,`Could not reach ${x},${z}; at ${p[0]},${p[2]}`);
};
const interact=async label=>{await page.keyboard.press('KeyE');await wait(180);const s=await state();console.log(label,{pos:s.pos,phase:s.phase,keycards:s.keycards,power:s.power,called:s.elevatorCalled,seconds:Math.ceil(s.survivalSeconds),storyRead:s.storyRead,nearest:s.nearestInteraction,toast:(await page.locator('#toast').textContent())?.trim()});return s;};
try {
 await page.goto('http://127.0.0.1:8000/',{waitUntil:'domcontentloaded',timeout:90000});await wait(1200);
 await page.locator('[data-action="intro"]').click();await page.locator('#skip-intro').click({force:true});await wait(350);
 await interact('journal');await walkTo(2.4,-4.4);await interact('security');
 await walkTo(0,-11);console.log('ward approach',(await state()).pos);
 await walkTo(-4.3,-18.5);console.log('MED approach',(await state()).pos);let s=await interact('MED keycard');assert.ok(s.keycards>=1,'MED card missing');
 await walkTo(0,-24);await interact('MED gate');
 console.log('ERRORS',errors);
} catch(e) { console.error('CHECK FAILED',e);console.log('AT',await state().catch(()=>null));console.log('ERRORS',errors);process.exitCode=1; }
finally {await browser.close();}

