const walkTo = async (x,z) => {
  const step=.35,s=await state(),[sx,,sz]=s.pos,cs=s.colliders.filter(c=>!c.disabled);
  const nx=Math.round(12/step),nz=Math.round(102/step),key=(i,j)=>`${i},${j}`;
  const toGrid=(px,pz)=>[Math.round((px+6)/step),Math.round((pz+95)/step)];
  const fromGrid=(i,j)=>[-6+i*step,-95+j*step];
  const [si,sj]=toGrid(sx,sz),[gi,gj]=toGrid(x,z);
  const blocked=(i,j)=>{if(i<1||i>nx-1||j<1||j>nz-1)return true;const [px,pz]=fromGrid(i,j);return cs.some(c=>Math.abs(px-c.x)<c.w/2+.39&&Math.abs(pz-c.z)<c.d/2+.39);};
  const q=[[si,sj]],prev=new Map([[key(si,sj),null]]);let end=null;
  for(let n=0;n<q.length;n++){const [i,j]=q[n];if(Math.hypot(i-gi,j-gj)<=1.4){end=[i,j];break;}for(const [di,dj] of [[1,0],[-1,0],[0,1],[0,-1]]){const a=i+di,b=j+dj,k=key(a,b);if(!prev.has(k)&&!blocked(a,b)){prev.set(k,[i,j]);q.push([a,b]);}}}
  if(!end)throw new Error(`No path ${sx.toFixed(1)},${sz.toFixed(1)} -> ${x},${z}`);
  const path=[];while(end){path.push(end);end=prev.get(key(...end));}path.reverse();
  let p=1;
  while(p<path.length){const [i0,j0]=path[p-1],[i1,j1]=path[p];const di=Math.sign(i1-i0),dj=Math.sign(j1-j0);let q=p+1;while(q<path.length&&Math.sign(path[q][0]-path[q-1][0])===di&&Math.sign(path[q][1]-path[q-1][1])===dj)q++;
    const dist=(q-p)*step,keys=[];if(di)keys.push(di>0?'d':'a');if(dj)keys.push(dj>0?'s':'w');keys.push('Shift');for(const k of keys)await page.keyboard.down(k);await wait(Math.max(50,dist/5.15*970));for(const k of keys)await page.keyboard.up(k);p=q;
  }
  const endPos=(await state()).pos;assert.ok(Math.hypot(endPos[0]-x,endPos[2]-z)<1.2,`Could not reach ${x},${z}; at ${endPos[0]},${endPos[2]}`);
};

