const walkTo = async (x,z) => {
  const step=.35,nx=34,nz=280,key=(i,j)=>`${i},${j}`;
  const toGrid=(px,pz)=>[Math.max(1,Math.min(nx-1,Math.round((px+6)/step))),Math.max(1,Math.min(nz-1,Math.round((pz+95)/step)))];
  const fromGrid=(i,j)=>[-6+i*step,-95+j*step];
  for(let attempt=0;attempt<220;attempt++){
    const s=await state(),[sx,,sz]=s.pos;if(Math.hypot(sx-x,sz-z)<.9)return;
    const cs=s.colliders.filter(c=>!c.disabled),[si,sj]=toGrid(sx,sz),[gi,gj]=toGrid(x,z);
    const blocked=(i,j)=>{if(i<1||i>=nx||j<1||j>=nz)return true;const [px,pz]=fromGrid(i,j);return cs.some(c=>Math.abs(px-c.x)<c.w/2+.38&&Math.abs(pz-c.z)<c.d/2+.38);};
    const q=[[si,sj]],prev=new Map([[key(si,sj),null]]);let end=null;
    for(let n=0;n<q.length;n++){const [i,j]=q[n];if(Math.hypot(i-gi,j-gj)<=2.0){end=[i,j];break;}for(const [di,dj] of [[1,0],[-1,0],[0,1],[0,-1]]){const a=i+di,b=j+dj,k=key(a,b);if(!prev.has(k)&&!blocked(a,b)){prev.set(k,[i,j]);q.push([a,b]);}}}
    if(!end)throw new Error(`No path ${sx.toFixed(1)},${sz.toFixed(1)} -> ${x},${z}`);
    const path=[];while(end){path.push(end);end=prev.get(key(...end));}path.reverse();
    const [i,j]=path[Math.min(2,path.length-1)],[px,pz]=fromGrid(i,j),dx=px-sx,dz=pz-sz;
    const keys=Math.abs(dx)>Math.abs(dz)?[dx>0?'d':'a']:[dz>0?'s':'w'];
    const before=Math.hypot(sx-x,sz-z);await move(keys[0],Math.max(90,Math.min(190,Math.hypot(dx,dz)/3.05*1000)));
    const after=(await state()).pos;if(Math.hypot(after[0]-x,after[2]-z)>=before-.025&&attempt>8)throw new Error(`Movement blocked at ${after[0].toFixed(2)},${after[2].toFixed(2)} on way to ${x},${z}`);
  }
  const endPos=(await state()).pos;assert.ok(Math.hypot(endPos[0]-x,endPos[2]-z)<1.2,`Could not reach ${x},${z}; at ${endPos[0]},${endPos[2]}`);
};

