import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, args: [...config.browser.launchOptions.args, '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors=[];
page.on('pageerror', e=>errors.push('PAGE '+e.message));
page.on('response', r=>{if(r.status()>=400&&!r.url().endsWith('favicon.ico'))errors.push(`HTTP ${r.status()} ${r.url()}`)});
page.on('console',m=>{if(m.type()==='error')errors.push('CONSOLE '+m.text())});
const wait=ms=>page.waitForTimeout(ms);
const state=()=>page.evaluate(()=>window.__facilityDebug());
const move=async(key,ms)=>{await page.keyboard.down(key);await wait(ms);await page.keyboard.up(key);await wait(100)};
const goX=async x=>{const p=(await state()).pos,dx=x-p[0];if(Math.abs(dx)>.15)await move(dx>0?'d':'a',Math.abs(dx)/3.05*1000)};
const goZ=async z=>{const p=(await state()).pos,dz=z-p[2];if(Math.abs(dz)>.15)await move(dz>0?'s':'w',Math.abs(dz)/3.05*1000)};
const at=async(x,z)=>{await goX(x);await goZ(z);const p=(await state()).pos;console.log('at',x,z,p.map(v=>+v.toFixed(2)));};
const interact=async label=>{await page.keyboard.press('KeyE');await wait(180);const s=await state();console.log(label,{pos:s.pos.map(v=>+v.toFixed(2)),phase:s.phase,keycards:s.keycards,power:s.power,called:s.elevatorCalled,seconds:Math.ceil(s.survivalSeconds),storyRead:s.storyRead,nearest:s.nearestInteraction,toast:(await page.locator('#toast').textContent())?.trim()});return s;};
try{
 await page.goto('http://127.0.0.1:8000/',{waitUntil:'domcontentloaded',timeout:20000});await wait(1000);
 await page.locator('[data-action="intro"]').click();await page.locator('#skip-intro').click({force:true});await wait(300);
 await interact('journal');await at(-2.2,-4.8);await at(2.4,-4.8);await interact('security');await at(0,-4.8);await at(0,-11);
 await at(-4,-19);let s=await interact('MED keycard');assert.ok(s.keycards>=1,'MED card missing');
 await at(0,-24);s=await interact('MED gate');assert.ok(s.phase>=2,'MED gate failed');
 await at(4,-42);s=await interact('LAB keycard');assert.ok(s.keycards>=2,'LAB card missing');
 await at(0,-47);s=await interact('LAB gate');assert.ok(s.phase>=3,'LAB gate failed');
 await at(-3,-55);s=await interact('REACTOR keycard');assert.ok(s.keycards>=3,'REACTOR card missing');
 await at(4,-62.2);s=await interact('generator');assert.ok(s.power,'Generator failed');
 await at(0,-68.5);await interact('elevator access');
 await at(3.35,-82);s=await interact('call elevator');assert.ok(s.elevatorCalled,'Elevator call failed');
 console.log('waiting 60 seconds for survival timer');await wait(61000);s=await state();console.log('timer',{seconds:Math.ceil(s.survivalSeconds),health:s.health,pos:s.pos});assert.ok(s.survivalSeconds<=0,'Timer did not finish');
 await interact('escape ending');await wait(300);assert.equal(await page.locator('#ending-title').textContent(),'OBERFLÄCHE ERREICHT.');
 console.log('PASS',errors);
}catch(e){console.error('CHECK FAILED',e);console.log('AT',await state().catch(()=>null));console.log('ERRORS',errors);process.exitCode=1}
finally{await browser.close()}

