import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, args: [...config.browser.launchOptions.args, '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors=[];
page.on('pageerror', e=>errors.push('PAGE '+e.message));
page.on('response', r=>{if(r.status()>=400&&!r.url().endsWith('favicon.ico'))errors.push(`HTTP ${r.status()} ${r.url()}`)});
page.on('console',m=>{if(m.type()==='error')errors.push('CONSOLE '+m.text())});
const state=()=>page.evaluate(()=>window.__facilityDebug());
const at=(x,z)=>page.evaluate(([x,z])=>window.__facilityTest.setPos(x,z),[x,z]);
const interact=async(x,z,label)=>{await at(x,z);await page.evaluate(()=>window.__facilityTest.interact());await page.waitForTimeout(100);const s=await state();console.log(label,{pos:s.pos,phase:s.phase,keycards:s.keycards,power:s.power,called:s.elevatorCalled,seconds:Math.ceil(s.survivalSeconds),storyRead:s.storyRead,nearest:s.nearestInteraction,toast:(await page.locator('#toast').textContent())?.trim()});return s;};
try {
 await page.goto('http://127.0.0.1:8000/',{waitUntil:'domcontentloaded',timeout:90000});await page.waitForTimeout(500);
 await page.locator('[data-action="intro"]').click();await page.locator('#skip-intro').click({force:true});
 await interact(0,2.4,'start');
 await interact(0,-4.2,'security');
 await interact(-4,-19,'MED card');assert.ok((await state()).keycards>=1);
 await interact(0,-24.1,'MED gate');assert.ok((await state()).phase>=2);
 await interact(4,-42,'LAB card');assert.ok((await state()).keycards>=2);
 await interact(0,-48,'LAB gate');assert.ok((await state()).phase>=3);
 await interact(-3,-55,'REACTOR card');assert.ok((await state()).keycards>=3);
 await interact(4,-62,'generator');assert.ok((await state()).power);
 await interact(0,-69.5,'elevator access');
 await interact(3.35,-82,'call elevator');assert.ok((await state()).elevatorCalled);
 await page.evaluate(()=>window.__facilityTest.finishTimer());
 await interact(3.35,-82,'escape ending');
 assert.equal(await page.locator('#ending-title').textContent(),'OBERFLÄCHE ERREICHT.');
 assert.deepEqual(errors,[]);
 console.log('PASS',errors);
} catch(e){console.error('CHECK FAILED',e);console.log('AT',await state().catch(()=>null));console.log('ERRORS',errors);process.exitCode=1;}
finally{await browser.close();}

