 function handleAction(action){switch(action){case'intro':beginIntro();break;case'settings':setScreen('settings-screen');break;case'lobby':game.botCount=1;localize();setScreen('lobby-screen');break;case'back':setScreen(game.mode==='menu'?'main-menu':'lobby-screen');break;case'backLobby':setScreen('lobby-screen');break;case'host':case'quick':game.roomCode=Math.random().toString(36).slice(2,6).toUpperCase();$('#room-code').textContent=game.roomCode;$('#lobby-status').textContent=tr('LOKALER TESTRAUM · KEIN ONLINE-MATCHMAKING','LOCAL TEST LOBBY · NO ONLINE MATCHMAKING');setScreen('room-screen');break;case'offline':game.botCount=1;setupRoomBots();setScreen('room-screen');break;case'launch':beginGame();break;case'resume':setPaused(false);break;case'quit':case'menu':game.mode='menu';game.paused=false;game.ending=false;$('#game-ui').classList.remove('active');$('#ending-screen').classList.remove('show');$('#pause-screen').classList.remove('show');setScreen('main-menu');document.exitPointerLock?.();break;}}
 function setupRoomBots(){game.roomCode=tr('OFFLINE · KI-TEAM','OFFLINE · BOT TEAM');$('#room-code').textContent=game.roomCode;$('#lobby-status').textContent=tr('OFFLINE-KI-TEAM · LOKALES SPIEL','OFFLINE BOT TEAM · LOCAL GAME');}
